import { describe, it, expect, vi, beforeEach } from 'vitest';
import request from 'supertest';
import { createAuthenticatedTestApp } from '../helpers/testApp';

// ─── Mock middleware ──────────────────────────────────────────────────────────

vi.mock('../../middleware/auth', () => ({
  default: (_req: any, _res: any, next: any) => next(),
}));

vi.mock('../../middleware/cacheControl', () => ({
  noCache: (_req: any, _res: any, next: any) => next(),
  cacheControl: () => (_req: any, _res: any, next: any) => next(),
}));

vi.mock('../../middleware/etag', () => ({
  etagMiddleware: () => (_req: any, _res: any, next: any) => next(),
  generateWeakETag: vi.fn(),
  generateStrongETag: vi.fn(),
  generateETag: vi.fn(),
}));

// ─── Mock database ────────────────────────────────────────────────────────────

vi.mock('../../config/database', () => ({
  default: {
    session: {
      findFirst: vi.fn(),
    },
    comment: {
      findUnique: vi.fn(),
      findMany: vi.fn(),
      create: vi.fn(),
      update: vi.fn(),
      delete: vi.fn(),
    },
    commentMention: {
      create: vi.fn(),
    },
    $transaction: vi.fn(),
  },
}));

// ─── Mock email / notification helpers ───────────────────────────────────────

vi.mock('../../utils/emailService', () => ({
  sendEmail: vi.fn().mockResolvedValue(undefined),
}));

vi.mock('../../utils/notificationHelper', () => ({
  batchShouldSendEmailNotification: vi.fn().mockResolvedValue(new Map()),
}));

import prisma from '../../config/database';
import commentRoutes from '../../routes/commentRoutes';
import { NotFoundError } from '../../utils/errors';

const app = createAuthenticatedTestApp(commentRoutes, 'test-user-id', '/api/comments');

const mockSession = {
  id: 'session-1',
  title: 'Test Session',
  group: {
    members: [
      { user: { id: 'test-user-id', name: 'Test User', email: 'test@example.com' } },
    ],
  },
};

const mockComment = {
  id: 'comment-1',
  content: 'Hello',
  sessionId: 'session-1',
  userId: 'test-user-id',
  parentId: null,
  createdAt: new Date('2024-01-01'),
  updatedAt: new Date('2024-01-01'),
  user: { id: 'test-user-id', name: 'Test User', email: 'test@example.com' },
  replies: [],
};

describe('Comment Controller', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    // Default $transaction implementation passes prisma as tx
    vi.mocked((prisma as any).$transaction).mockImplementation(async (cb: any) => cb(prisma));
  });

  // ─── POST /api/comments ────────────────────────────────────────────────

  describe('POST /api/comments', () => {
    it('returns 400 when sessionId or content is missing', async () => {
      const res = await request(app).post('/api/comments').send({ content: 'Hi' }); // no sessionId
      expect(res.status).toBe(400);

      const res2 = await request(app).post('/api/comments').send({ sessionId: 'session-1' }); // no content
      expect(res2.status).toBe(400);
    });

    it('returns 404 when session is not found', async () => {
      vi.mocked(prisma.session.findFirst).mockResolvedValue(null);

      const res = await request(app)
        .post('/api/comments')
        .send({ sessionId: 'nonexistent', content: 'Hello' });

      expect(res.status).toBe(404);
    });

    it('returns 201 when comment is created successfully', async () => {
      vi.mocked(prisma.session.findFirst).mockResolvedValue(mockSession as any);
      vi.mocked(prisma.comment.create).mockResolvedValue(mockComment as any);

      const res = await request(app)
        .post('/api/comments')
        .send({ sessionId: 'session-1', content: 'Hello' });

      expect(res.status).toBe(201);
      expect(res.body).toMatchObject({ id: 'comment-1', content: 'Hello' });
    });
  });

  // ─── GET /api/comments/session/:sessionId ─────────────────────────────

  describe('GET /api/comments/session/:sessionId', () => {
    it('returns 404 when session is not found', async () => {
      vi.mocked(prisma.session.findFirst).mockResolvedValue(null);

      const res = await request(app).get('/api/comments/session/nonexistent');

      expect(res.status).toBe(404);
    });

    it('returns 200 with comments', async () => {
      vi.mocked(prisma.session.findFirst).mockResolvedValue(mockSession as any);
      vi.mocked(prisma.comment.findMany).mockResolvedValue([mockComment] as any);

      const res = await request(app).get('/api/comments/session/session-1');

      expect(res.status).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body[0]).toMatchObject({ id: 'comment-1' });
    });
  });

  // ─── PUT /api/comments/:commentId ─────────────────────────────────────

  describe('PUT /api/comments/:commentId', () => {
    it('returns 400 when content is missing', async () => {
      const res = await request(app)
        .put('/api/comments/comment-1')
        .send({});

      expect(res.status).toBe(400);
    });

    it('returns 404 when comment is not found', async () => {
      vi.mocked(prisma.comment.findUnique).mockResolvedValue(null);

      const res = await request(app)
        .put('/api/comments/nonexistent')
        .send({ content: 'Updated' });

      expect(res.status).toBe(404);
    });

    it('returns 403 when user is not the author', async () => {
      vi.mocked(prisma.comment.findUnique).mockResolvedValue({
        ...mockComment,
        userId: 'other-user-id',
      } as any);

      const res = await request(app)
        .put('/api/comments/comment-1')
        .send({ content: 'Updated' });

      expect(res.status).toBe(403);
    });

    it('returns 200 when comment is updated', async () => {
      vi.mocked(prisma.comment.findUnique).mockResolvedValue(mockComment as any);
      const updated = { ...mockComment, content: 'Updated content' };
      vi.mocked(prisma.comment.update).mockResolvedValue(updated as any);

      const res = await request(app)
        .put('/api/comments/comment-1')
        .send({ content: 'Updated content' });

      expect(res.status).toBe(200);
      expect(res.body).toMatchObject({ content: 'Updated content' });
    });
  });

  // ─── DELETE /api/comments/:commentId ──────────────────────────────────

  describe('DELETE /api/comments/:commentId', () => {
    it('returns 404 when comment is not found', async () => {
      vi.mocked(prisma.comment.findUnique).mockResolvedValue(null);

      const res = await request(app).delete('/api/comments/nonexistent');

      expect(res.status).toBe(404);
    });

    it('returns 403 when user is not the author', async () => {
      vi.mocked(prisma.comment.findUnique).mockResolvedValue({
        ...mockComment,
        userId: 'other-user-id',
      } as any);

      const res = await request(app).delete('/api/comments/comment-1');

      expect(res.status).toBe(403);
    });

    it('returns 200 when comment is deleted', async () => {
      vi.mocked(prisma.comment.findUnique).mockResolvedValue(mockComment as any);
      vi.mocked(prisma.comment.delete).mockResolvedValue(mockComment as any);

      const res = await request(app).delete('/api/comments/comment-1');

      expect(res.status).toBe(200);
      expect(res.body).toMatchObject({ message: 'Comment deleted successfully' });
    });
  });
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import request from 'supertest';
import express, { Router } from 'express';
import { createTestApp } from '../helpers/testApp';
import * as reminderController from '../../controllers/reminderController';

vi.mock('../../middleware/auth', () => ({
  default: (req: any, _res: any, next: any) => { req.user = { id: 'test-user-id', email: 'test@example.com', name: 'Test User' }; next(); },
  optionalAuthMiddleware: (req: any, _res: any, next: any) => { req.user = { id: 'test-user-id' }; next(); }
}));
vi.mock('../../middleware/rateLimiter', () => ({
  authenticatedLimiter: (_: any, __: any, next: any) => next(),
  apiLimiter: (_: any, __: any, next: any) => next(),
  authLimiter: (_: any, __: any, next: any) => next()
}));
vi.mock('../../middleware/distributedRateLimiter', () => ({
  distributedAuthLimiter: (_: any, __: any, next: any) => next(),
  distributedAuthenticatedLimiter: (_: any, __: any, next: any) => next(),
  distributedUploadLimiter: (_: any, __: any, next: any) => next(),
  distributedApiLimiter: (_: any, __: any, next: any) => next(),
  distributedPasswordResetLimiter: (_: any, __: any, next: any) => next(),
  distributedEmailVerificationLimiter: (_: any, __: any, next: any) => next()
}));
vi.mock('../../utils/logger', () => ({
  logger: { info: vi.fn(), error: vi.fn(), warn: vi.fn(), debug: vi.fn() }
}));

vi.mock('../../config/database', () => ({
  default: {
    session: { findFirst: vi.fn(), findUnique: vi.fn() },
    sessionReminder: {
      findUnique: vi.fn(),
      findMany: vi.fn(),
      create: vi.fn(),
      update: vi.fn(),
      delete: vi.fn()
    },
    $transaction: vi.fn()
  }
}));

import prisma from '../../config/database';

// Build a minimal router mounting the reminder endpoints
function buildReminderRouter(): Router {
  const router = Router({ mergeParams: true });

  router.post('/api/events/:sessionId/reminders', reminderController.createReminder);
  router.get('/api/events/:sessionId/reminders', reminderController.getEventReminders);
  router.get('/api/reminders', reminderController.getUserReminders);
  router.put('/api/reminders/:reminderId', reminderController.updateReminder);
  router.delete('/api/reminders/:reminderId', reminderController.deleteReminder);

  return router;
}

function createApp() {
  const app = express();
  app.use(express.json());
  // Inject mock user
  app.use((req: any, _res, next) => {
    req.user = { id: 'test-user-id', email: 'test@example.com', name: 'Test User' };
    next();
  });
  app.use(buildReminderRouter());
  return app;
}

describe('Reminder Controller', () => {
  const app = createApp();
  const futureDate = new Date(Date.now() + 3600 * 1000 * 24).toISOString();
  const pastDate = new Date(Date.now() - 3600 * 1000).toISOString();

  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('POST /api/events/:sessionId/reminders - createReminder', () => {
    it('returns 400 when remindAt is missing', async () => {
      const res = await request(app)
        .post('/api/events/session-1/reminders')
        .send({});
      expect(res.status).toBe(400);
    });

    it('returns 400 when remindAt is a past date', async () => {
      const res = await request(app)
        .post('/api/events/session-1/reminders')
        .send({ remindAt: pastDate });
      expect(res.status).toBe(400);
    });

    it('returns 404 when session not found', async () => {
      vi.mocked(prisma.session.findFirst).mockResolvedValue(null);

      const res = await request(app)
        .post('/api/events/session-1/reminders')
        .send({ remindAt: futureDate });
      expect(res.status).toBe(404);
    });

    it('returns 400 when a duplicate reminder exists', async () => {
      vi.mocked(prisma.session.findFirst).mockResolvedValue({
        id: 'session-1',
        startTime: new Date(Date.now() + 3600 * 1000 * 48)
      } as any);
      vi.mocked(prisma.sessionReminder.findUnique).mockResolvedValue({
        id: 'existing-reminder'
      } as any);

      const res = await request(app)
        .post('/api/events/session-1/reminders')
        .send({ remindAt: futureDate });
      expect(res.status).toBe(400);
    });

    it('returns 201 on successful creation', async () => {
      const remindAt = new Date(Date.now() + 3600 * 1000 * 24);
      vi.mocked(prisma.session.findFirst).mockResolvedValue({
        id: 'session-1',
        startTime: new Date(Date.now() + 3600 * 1000 * 48)
      } as any);
      vi.mocked(prisma.sessionReminder.findUnique).mockResolvedValue(null);
      vi.mocked(prisma.sessionReminder.create).mockResolvedValue({
        id: 'reminder-1',
        sessionId: 'session-1',
        userId: 'test-user-id',
        remindAt,
        sent: false,
        session: { id: 'session-1', title: 'Test', startTime: new Date() }
      } as any);

      const res = await request(app)
        .post('/api/events/session-1/reminders')
        .send({ remindAt: remindAt.toISOString() });
      expect(res.status).toBe(201);
      expect(res.body).toHaveProperty('reminder');
    });
  });

  describe('GET /api/events/:sessionId/reminders - getEventReminders', () => {
    it('returns 404 when user has no session access', async () => {
      vi.mocked(prisma.session.findFirst).mockResolvedValue(null);

      const res = await request(app).get('/api/events/session-1/reminders');
      expect(res.status).toBe(404);
    });

    it('returns 200 with reminders list', async () => {
      vi.mocked(prisma.session.findFirst).mockResolvedValue({ id: 'session-1' } as any);
      vi.mocked(prisma.sessionReminder.findMany).mockResolvedValue([
        { id: 'r1', remindAt: new Date() }
      ] as any);

      const res = await request(app).get('/api/events/session-1/reminders');
      expect(res.status).toBe(200);
      expect(res.body).toHaveProperty('reminders');
    });
  });

  describe('GET /api/reminders - getUserReminders', () => {
    it('returns 200 with all user reminders', async () => {
      vi.mocked(prisma.sessionReminder.findMany).mockResolvedValue([
        { id: 'r1', remindAt: new Date(), session: { id: 's1', title: 'Test' } }
      ] as any);

      const res = await request(app).get('/api/reminders');
      expect(res.status).toBe(200);
      expect(res.body).toHaveProperty('reminders');
    });
  });

  describe('PUT /api/reminders/:reminderId - updateReminder', () => {
    it('returns 400 when remindAt is missing', async () => {
      const res = await request(app)
        .put('/api/reminders/reminder-1')
        .send({});
      expect(res.status).toBe(400);
    });

    it('returns 404 when reminder not found', async () => {
      vi.mocked(prisma.sessionReminder.findUnique).mockResolvedValue(null);

      const res = await request(app)
        .put('/api/reminders/reminder-1')
        .send({ remindAt: futureDate });
      expect(res.status).toBe(404);
    });

    it('returns 403 when user is not the owner', async () => {
      vi.mocked(prisma.sessionReminder.findUnique).mockResolvedValue({
        id: 'reminder-1',
        userId: 'other-user-id',
        sessionId: 'session-1',
        session: { startTime: new Date(Date.now() + 3600 * 1000 * 48) }
      } as any);

      const res = await request(app)
        .put('/api/reminders/reminder-1')
        .send({ remindAt: futureDate });
      expect(res.status).toBe(403);
    });

    it('returns 200 on successful update', async () => {
      const newRemindAt = new Date(Date.now() + 3600 * 1000 * 24);
      vi.mocked(prisma.sessionReminder.findUnique).mockResolvedValue({
        id: 'reminder-1',
        userId: 'test-user-id',
        sessionId: 'session-1',
        session: { startTime: new Date(Date.now() + 3600 * 1000 * 48) }
      } as any);
      // No duplicate
      vi.mocked(prisma.sessionReminder.findUnique).mockResolvedValueOnce({
        id: 'reminder-1',
        userId: 'test-user-id',
        sessionId: 'session-1',
        session: { startTime: new Date(Date.now() + 3600 * 1000 * 48) }
      } as any).mockResolvedValueOnce(null);

      const updatedReminder = {
        id: 'reminder-2',
        sessionId: 'session-1',
        userId: 'test-user-id',
        remindAt: newRemindAt,
        session: { id: 'session-1', title: 'Test', startTime: new Date() }
      };
      vi.mocked(prisma.$transaction).mockResolvedValue([undefined, updatedReminder] as any);

      const res = await request(app)
        .put('/api/reminders/reminder-1')
        .send({ remindAt: newRemindAt.toISOString() });
      expect(res.status).toBe(200);
      expect(res.body).toHaveProperty('reminder');
    });
  });

  describe('DELETE /api/reminders/:reminderId - deleteReminder', () => {
    it('returns 404 when reminder not found', async () => {
      vi.mocked(prisma.sessionReminder.findUnique).mockResolvedValue(null);

      const res = await request(app).delete('/api/reminders/reminder-1');
      expect(res.status).toBe(404);
    });

    it('returns 403 when user is not the owner', async () => {
      vi.mocked(prisma.sessionReminder.findUnique).mockResolvedValue({
        id: 'reminder-1',
        userId: 'other-user-id'
      } as any);

      const res = await request(app).delete('/api/reminders/reminder-1');
      expect(res.status).toBe(403);
    });

    it('returns 200 on successful deletion', async () => {
      vi.mocked(prisma.sessionReminder.findUnique).mockResolvedValue({
        id: 'reminder-1',
        userId: 'test-user-id'
      } as any);
      vi.mocked(prisma.sessionReminder.delete).mockResolvedValue({} as any);

      const res = await request(app).delete('/api/reminders/reminder-1');
      expect(res.status).toBe(200);
      expect(res.body).toHaveProperty('message');
    });
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import {
  initializeQueryMonitoring,
  queryMonitorMiddleware,
  trackQuery,
  batchQuery,
} from '../../middleware/queryMonitor';

vi.mock('../../utils/logger', () => ({
  logger: {
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  },
}));

// Mock the dynamic import used in getConnectionPoolStats
vi.mock('../../config/database', () => ({
  getPool: vi.fn(() => ({})),
}));

import { logger } from '../../utils/logger';

let reqIdCounter = 0;

const createMockReqRes = (overrides: Record<string, unknown> = {}) => {
  const req: any = {
    method: 'GET',
    path: '/test',
    id: `req-${++reqIdCounter}`,
    ...overrides,
  };
  const res: any = {
    end: vi.fn(),
  };
  const next = vi.fn();
  return { req, res, next };
};

describe('initializeQueryMonitoring', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('calls logger.info', () => {
    initializeQueryMonitoring();
    expect(logger.info).toHaveBeenCalledWith(
      'Query monitoring initialized',
      'QueryMonitor'
    );
  });
});

describe('queryMonitorMiddleware', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('calls next()', () => {
    const { req, res, next } = createMockReqRes();
    queryMonitorMiddleware()(req, res, next);
    expect(next).toHaveBeenCalledOnce();
  });

  it('patches res.end to a new function', () => {
    const { req, res, next } = createMockReqRes();
    const originalEnd = res.end;
    queryMonitorMiddleware()(req, res, next);
    expect(res.end).not.toBe(originalEnd);
  });

  it('does NOT call logger.warn when there are no slow queries and count < 50', () => {
    const { req, res, next } = createMockReqRes();
    queryMonitorMiddleware()(req, res, next);

    // A couple of normal-speed queries
    trackQuery(req.id, 'SELECT 1', 100);
    trackQuery(req.id, 'SELECT 2', 200);

    res.end();

    expect(logger.warn).not.toHaveBeenCalled();
  });

  it('calls logger.warn with slow query info when slow queries exist', () => {
    const { req, res, next } = createMockReqRes();
    queryMonitorMiddleware()(req, res, next);

    // Slow query: duration > 1000ms
    trackQuery(req.id, 'SELECT slow_thing FROM big_table', 1500);

    res.end();

    expect(logger.warn).toHaveBeenCalledWith(
      'Request with slow queries detected',
      'QueryMonitor',
      expect.objectContaining({
        method: 'GET',
        path: '/test',
        slowQueries: expect.arrayContaining([
          expect.objectContaining({ duration: 1500 }),
        ]),
      })
    );
  });

  it('calls logger.warn with high query count when query count exceeds 50', () => {
    const { req, res, next } = createMockReqRes();
    queryMonitorMiddleware()(req, res, next);

    // Add 51 queries with normal duration
    for (let i = 0; i < 51; i++) {
      trackQuery(req.id, `SELECT ${i}`, 10);
    }

    res.end();

    expect(logger.warn).toHaveBeenCalledWith(
      'Request with high query count',
      'QueryMonitor',
      expect.objectContaining({ queryCount: 51 })
    );
  });

  it('cleans up the metrics entry from the store after res.end()', () => {
    const { req, res, next } = createMockReqRes();
    queryMonitorMiddleware()(req, res, next);

    res.end();
    vi.clearAllMocks();

    // Calling trackQuery after end should be a no-op (entry was deleted)
    expect(() => trackQuery(req.id, 'SELECT 1', 9999)).not.toThrow();
    // No additional warn since the store no longer has the entry
    expect(logger.warn).not.toHaveBeenCalled();
  });
});

describe('trackQuery', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('does not throw when requestId is undefined', () => {
    expect(() => trackQuery(undefined, 'SELECT 1', 100)).not.toThrow();
  });

  it('does not throw when requestId is unknown (not in store)', () => {
    expect(() => trackQuery('nonexistent-id', 'SELECT 1', 100)).not.toThrow();
  });

  it('does not call logger.error for a normal duration query', () => {
    const { req, res, next } = createMockReqRes();
    queryMonitorMiddleware()(req, res, next);

    trackQuery(req.id, 'SELECT 1', 500);

    expect(logger.error).not.toHaveBeenCalled();
    res.end();
  });

  it('adds query to slowQueries when duration exceeds 1000ms', () => {
    const { req, res, next } = createMockReqRes();
    queryMonitorMiddleware()(req, res, next);

    trackQuery(req.id, 'SELECT * FROM large_table', 1200);

    res.end();

    expect(logger.warn).toHaveBeenCalledWith(
      'Request with slow queries detected',
      'QueryMonitor',
      expect.objectContaining({
        slowQueries: expect.arrayContaining([
          expect.objectContaining({ query: 'SELECT * FROM large_table', duration: 1200 }),
        ]),
      })
    );
  });

  it('calls logger.error immediately when duration exceeds 3000ms', () => {
    const { req, res, next } = createMockReqRes();
    queryMonitorMiddleware()(req, res, next);

    trackQuery(req.id, 'SELECT * FROM very_large_table', 5000);

    expect(logger.error).toHaveBeenCalledWith(
      'Very slow query detected',
      'QueryMonitor',
      expect.objectContaining({ duration: 5000 })
    );
    res.end();
  });

  it('truncates long query strings to 200 characters in slowQueries', () => {
    const { req, res, next } = createMockReqRes();
    queryMonitorMiddleware()(req, res, next);

    const longQuery = 'SELECT ' + 'a'.repeat(300);
    trackQuery(req.id, longQuery, 1500);

    res.end();

    expect(logger.warn).toHaveBeenCalledWith(
      'Request with slow queries detected',
      'QueryMonitor',
      expect.objectContaining({
        slowQueries: expect.arrayContaining([
          expect.objectContaining({
            query: longQuery.substring(0, 200),
          }),
        ]),
      })
    );
  });
});

describe('batchQuery', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('executes all queries in parallel and returns results', async () => {
    const queries = [
      vi.fn().mockResolvedValue('result-1'),
      vi.fn().mockResolvedValue('result-2'),
      vi.fn().mockResolvedValue('result-3'),
    ];

    const results = await batchQuery(queries, { parallel: true });

    expect(results).toEqual(['result-1', 'result-2', 'result-3']);
    queries.forEach(q => expect(q).toHaveBeenCalledOnce());
  });

  it('executes all queries sequentially when parallel is false', async () => {
    const callOrder: number[] = [];
    const queries = [0, 1, 2].map(i =>
      vi.fn().mockImplementation(async () => {
        callOrder.push(i);
        return `result-${i}`;
      })
    );

    const results = await batchQuery(queries, { parallel: false });

    expect(results).toEqual(['result-0', 'result-1', 'result-2']);
    expect(callOrder).toEqual([0, 1, 2]);
  });

  it('respects batchSize when splitting queries into chunks', async () => {
    const queries = Array.from({ length: 5 }, (_, i) =>
      vi.fn().mockResolvedValue(`r${i}`)
    );

    const results = await batchQuery(queries, { parallel: true, batchSize: 2 });

    expect(results).toHaveLength(5);
    queries.forEach(q => expect(q).toHaveBeenCalledOnce());
  });

