let testJwkN: string;
let testJwkE: string;
const TEST_KID = 'test-apple-kid';

beforeAll(() => {
  const { publicKey } = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });
  const jwk = publicKey.export({ format: 'jwk' }) as { n: string; e: string };
  testJwkN = jwk.n;
  testJwkE = jwk.e;
});

